import { fromJS } from 'immutable';
import {
  convertCelsiusTemperatureToUnit,
  getStandardUnitName,
  getUnitDisplayName,
  hasRange,
  isProbeSupportedUnit,
  isTemperatureUnit,
  isUnitStandard,
  isWeightUnit,
  UNIT_MODE,
  UNIT_TYPES,
} from '../../';

describe('Measurement Utility', () => {
  it('getUnitDisplayName gets symbol if exists', () => {
    const symbol = getUnitDisplayName('CELSIUS');
    expect(symbol).toBe('°C');
  });

  it('getUnitDisplayName returns provided unit name if not exists', () => {
    const unitName = 'my units';
    const result = getUnitDisplayName(unitName);
    expect(result).toBe(unitName);
  });

  describe('isUnitStandard', () => {
    it('custom js', () => {
      const result = isUnitStandard({ type: UNIT_MODE.CUSTOM });
      expect(result).toEqual(false);
    });

    it('standard js', () => {
      const result = isUnitStandard({ type: UNIT_MODE.STANDARD });
      expect(result).toEqual(true);
    });

    it('custom immutable', () => {
      const unit = fromJS({ type: UNIT_MODE.CUSTOM });
      const result = isUnitStandard(unit);
      expect(result).toEqual(false);
    });

    it('standard immutable', () => {
      const unit = fromJS({ type: UNIT_MODE.STANDARD });
      const result = isUnitStandard(unit);
      expect(result).toEqual(true);
    });
  });

  describe('isProbeSupportedUnit', () => {
    it('pH js', () => {
      const result = isProbeSupportedUnit({
        name: UNIT_TYPES.PH.symbol,
        type: UNIT_MODE.STANDARD,
      });
      expect(result).toEqual(false);
    });

    it('celsius js', () => {
      const result = isProbeSupportedUnit({
        name: UNIT_TYPES.CELSIUS.symbol,
        type: UNIT_MODE.STANDARD,
      });
      expect(result).toEqual(true);
    });

    it('celsius js custom', () => {
      const result = isProbeSupportedUnit({
        name: UNIT_TYPES.CELSIUS.symbol,
        type: UNIT_MODE.CUSTOM,
      });
      expect(result).toEqual(false);
    });

    it('pH immutable', () => {
      const unit = fromJS({
        name: UNIT_TYPES.PH.symbol,
        type: UNIT_MODE.STANDARD,
      });
      const result = isProbeSupportedUnit(unit);
      expect(result).toEqual(false);
    });

    it('celsius immutable', () => {
      const unit = fromJS({
        name: UNIT_TYPES.CELSIUS.symbol,
        type: UNIT_MODE.STANDARD,
      });
      const result = isProbeSupportedUnit(unit);
      expect(result).toEqual(true);
    });

    it('celsius immutable custom', () => {
      const unit = fromJS({
        name: UNIT_TYPES.CELSIUS.symbol,
        type: UNIT_MODE.CUSTOM,
      });
      const result = isProbeSupportedUnit(unit);
      expect(result).toEqual(false);
    });

    it('celsius encoding immutable', () => {
      const unit = fromJS({
        name: '°C',
        type: UNIT_MODE.STANDARD,
      });
      const result = isProbeSupportedUnit(unit);
      expect(result).toEqual(true);
    });

    it('celsius not encoding immutable', () => {
      const unit = fromJS({
        name: '˚C',
        type: UNIT_MODE.STANDARD,
      });
      const result = isProbeSupportedUnit(unit);
      expect(result).toEqual(true);
    });

    it('celsius short value immutable', () => {
      const unit = fromJS({
        name: 'C',
        type: UNIT_MODE.STANDARD,
      });
      const result = isProbeSupportedUnit(unit);
      expect(result).toEqual(false);
    });
  });
});

describe('getStandardUnitName', () => {
  const cId = 'c1';
  const fId = 'f1';
  const kId = 'k1';
  const phId = 'ph1';
  const tpmId = 'tpm1';
  const gramsId = 'g1';
  const kgId = 'kg1';
  const ozId = 'oz1';
  const lbId = 'lb1';
  const units = fromJS([
    {
      id: cId,
      name: '°C',
      type: UNIT_MODE.STANDARD,
    },
    {
      id: fId,
      name: '°F',
      type: UNIT_MODE.STANDARD,
    },
    {
      id: kId,
      name: '°K',
      type: UNIT_MODE.STANDARD,
    },
    {
      id: phId,
      name: 'pH',
      type: UNIT_MODE.STANDARD,
    },
    {
      id: tpmId,
      name: 'TPM',
      type: UNIT_MODE.STANDARD,
    },
    {
      id: gramsId,
      name: 'g',
      type: UNIT_MODE.STANDARD,
    },
    {
      id: kgId,
      name: 'kg',
      type: UNIT_MODE.STANDARD,
    },
    {
      id: ozId,
      name: 'oz',
      type: UNIT_MODE.STANDARD,
    },
    {
      id: lbId,
      name: 'lb',
      type: UNIT_MODE.STANDARD,
    },
  ]);

  it('C', () => {
    expect(getStandardUnitName(units, cId)).toEqual('CELSIUS');
  });

  it('F', () => {
    expect(getStandardUnitName(units, fId)).toEqual('FAHRENHEIT');
  });

  it('H', () => {
    expect(getStandardUnitName(units, phId)).toEqual('PH');
  });

  it('K', () => {
    expect(getStandardUnitName(units, kId)).toEqual('KELVIN');
  });

  it('P', () => {
    expect(getStandardUnitName(units, tpmId)).toEqual('TPM');
  });

  it('g (grams)', () => {
    expect(getStandardUnitName(units, gramsId)).toEqual('GRAMS');
  });

  it('kg (kilograms)', () => {
    expect(getStandardUnitName(units, kgId)).toEqual('KILOGRAMS');
  });

  it('oz (ounces)', () => {
    expect(getStandardUnitName(units, ozId)).toEqual('OUNCES');
  });

  it('lb (pounds)', () => {
    expect(getStandardUnitName(units, lbId)).toEqual('POUNDS');
  });

  it('default', () => {
    expect(getStandardUnitName(units, 'fake')).toEqual(null);
  });
});

describe('hasRange', () => {
  it('instance.hasRange returns false when minValue2 or maxValue2 are not set', () => {
    expect(hasRange(null, null)).toBe(false);
  });

  it('instance.hasRange returns true when both minValue2 or maxValue2 are set', () => {
    expect(hasRange(12.5, 20.3)).toBe(true);
  });

  it('instance.hasRange returns true when only minValue2 is set', () => {
    expect(hasRange('12.5', null)).toBe(true);
  });

  it('instance.hasRange returns true when only maxValue2 is set', () => {
    expect(hasRange(null, '20.3')).toBe(true);
  });
});

describe('convertCelsiusTemperatureToUnit', () => {
  it('return correct value for CELSIUS', () => {
    expect(convertCelsiusTemperatureToUnit(4, UNIT_TYPES.CELSIUS.string)).toBe(
      '4.00 °C',
    );
  });

  it('return correct value for FAHRENHEIT', () => {
    expect(
      convertCelsiusTemperatureToUnit(4, UNIT_TYPES.FAHRENHEIT.string),
    ).toBe('39.20 °F');
  });

  it('return correct value for KELVIN', () => {
    expect(convertCelsiusTemperatureToUnit(4, UNIT_TYPES.KELVIN.string)).toBe(
      '277.15 °K',
    );
  });
});

describe('isWeightUnit', () => {
  it('returns true for GRAMS', () => {
    expect(isWeightUnit('GRAMS')).toBe(true);
  });

  it('returns true for KILOGRAMS', () => {
    expect(isWeightUnit('KILOGRAMS')).toBe(true);
  });

  it('returns true for OUNCES', () => {
    expect(isWeightUnit('OUNCES')).toBe(true);
  });

  it('returns true for POUNDS', () => {
    expect(isWeightUnit('POUNDS')).toBe(true);
  });

  it('returns false for CELSIUS', () => {
    expect(isWeightUnit('CELSIUS')).toBe(false);
  });

  it('returns false for PH', () => {
    expect(isWeightUnit('PH')).toBe(false);
  });

  it('returns false for null', () => {
    expect(isWeightUnit(null)).toBe(false);
  });
});

describe('isTemperatureUnit', () => {
  it('returns true for CELSIUS', () => {
    expect(isTemperatureUnit('CELSIUS')).toBe(true);
  });

  it('returns true for FAHRENHEIT', () => {
    expect(isTemperatureUnit('FAHRENHEIT')).toBe(true);
  });

  it('returns true for KELVIN', () => {
    expect(isTemperatureUnit('KELVIN')).toBe(true);
  });

  it('returns false for GRAMS', () => {
    expect(isTemperatureUnit('GRAMS')).toBe(false);
  });

  it('returns false for PH', () => {
    expect(isTemperatureUnit('PH')).toBe(false);
  });

  it('returns false for null', () => {
    expect(isTemperatureUnit(null)).toBe(false);
  });
});
